    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def md(a, b, c, d):
        t = a - c
        if t < 0:
            t = -t
        u = b - d
        if u < 0:
            u = -u
        return t + u

    def min_dist_to_resources(x, y):
        if not res:
            return 999999
